    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    fn exercise_s3_dword_alias_load_base(
        instruction_base: u8,
        base_register: od_isa::Register,
        base_gpr_index: usize,
    ) {
        exercise_s3_dword_alias_load_with_disp(
            instruction_base,
            base_register,
            base_gpr_index,
            None,
        );
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    fn exercise_s3_dword_alias_load_with_disp(
        instruction_base: u8,
        base_register: od_isa::Register,
        base_gpr_index: usize,
        disp8: Option<i8>,
    ) {
        exercise_s3_dword_alias_load_with_encoded_disp(
            instruction_base,
            base_register,
            base_gpr_index,
            disp8.map(|displacement| vec![displacement as u8]),
        );
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    fn exercise_s3_dword_alias_load_with_disp32(
        instruction_base: u8,
        base_register: od_isa::Register,
        base_gpr_index: usize,
        displacement: i32,
    ) {
        exercise_s3_dword_alias_load_with_encoded_disp(
            instruction_base,
            base_register,
            base_gpr_index,
            Some(displacement.to_le_bytes().to_vec()),
        );
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    fn exercise_s3_dword_alias_load_with_encoded_disp(
        instruction_base: u8,
        base_register: od_isa::Register,
        base_gpr_index: usize,
        displacement_bytes: Option<Vec<u8>>,
    ) {
        use od_isa::memory::{AccessContext, AccessKind, GuestMemory, MemoryError};
        use std::collections::BTreeMap;
        use std::sync::Arc;

        const ENTRY: u64 = 0x9d80;
        const ADDRESS: u64 = 0x1_0000_0fff;
        let displacement = match displacement_bytes.as_deref() {
            None => 0,
            Some([disp8]) => i64::from(*disp8 as i8),
            Some([a, b, c, d]) => i64::from(i32::from_le_bytes([*a, *b, *c, *d])),
            Some(_) => unreachable!("disp32 fixture uses one or four encoded bytes"),
        };
        let next_rip = ENTRY + 2 + displacement_bytes.as_ref().map_or(0, |bytes| bytes.len() as u64);
        let base_for_address = |address: u64| address.wrapping_sub_signed(displacement);
        let original_base = base_for_address(ADDRESS);
        let mut source = vec![0x8b, instruction_base];
        if let Some(displacement) = &displacement_bytes {
            source.extend_from_slice(displacement);
        }
        #[derive(Clone, Debug)]
        struct AliasRam {
            bytes: BTreeMap<u64, u8>,
            reads: Vec<(u64, usize)>,
            read_error: Option<MemoryError>,
            instruction_base: u8,
            instruction_displacement: Option<Vec<u8>>,
            stop_on_read: Option<Arc<AtomicU8>>,
        }
        impl PartialEq for AliasRam {
            fn eq(&self, other: &Self) -> bool {
                self.bytes == other.bytes
                    && self.reads == other.reads
                    && self.read_error == other.read_error
                    && self.instruction_base == other.instruction_base
                    && self.instruction_displacement == other.instruction_displacement
                    && match (&self.stop_on_read, &other.stop_on_read) {
                        (None, None) => true,
                        (Some(left), Some(right)) => Arc::ptr_eq(left, right),
                        _ => false,
                    }
            }
        }
        impl Eq for AliasRam {}
        impl GuestMemory for AliasRam {
            fn fetch(&mut self, address: u64, _: AccessContext) -> Result<u8, MemoryError> {
                match address {
                    ENTRY => Ok(0x8b),
                    address if address == ENTRY + 1 => Ok(self.instruction_base),
                    address if (ENTRY + 2..ENTRY + 6).contains(&address) => self
                        .instruction_displacement
                        .as_ref()
                        .and_then(|bytes| bytes.get((address - (ENTRY + 2)) as usize))
                        .copied()
                        .ok_or(MemoryError::Unmapped {
                            address,
                            access: AccessKind::Fetch,
                        }),
                    _ => self
                        .bytes
                        .get(&address)
                        .copied()
                        .ok_or(MemoryError::Unmapped {
                            address,
                            access: AccessKind::Fetch,
                        }),
                }
            }

            fn read(
                &mut self,
                address: u64,
                _: AccessContext,
                output: &mut [u8],
            ) -> Result<(), MemoryError> {
                self.reads.push((address, output.len()));
                if let Some(error) = self.read_error.clone() {
                    return Err(error);
                }
                for (offset, byte) in output.iter_mut().enumerate() {
                    let current =
                        address
                            .checked_add(offset as u64)
                            .ok_or(MemoryError::Unmapped {
                                address,
                                access: AccessKind::Read,
                            })?;
                    *byte = *self.bytes.get(&current).ok_or(MemoryError::Unmapped {
                        address,
                        access: AccessKind::Read,
                    })?;
                }
                if let Some(stop) = &self.stop_on_read {
                    stop.store(1, Ordering::Release);
                }
                Ok(())
            }

            fn write(
                &mut self,
                address: u64,
                _: AccessContext,
                _: &[u8],
            ) -> Result<(), MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn atomic_exchange_integer(
                &mut self,
                address: u64,
                _: AccessContext,
                _: od_isa::OperandSize,
                _: u64,
            ) -> Result<u64, MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn atomic_fetch_add_integer(
                &mut self,
                address: u64,
                _: AccessContext,
                _: od_isa::OperandSize,
                _: u64,
            ) -> Result<u64, MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn atomic_compare_exchange_integer(
                &mut self,
                address: u64,
                _: AccessContext,
                _: od_isa::OperandSize,
                _: u64,
                _: u64,
            ) -> Result<u64, MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn mfence(&mut self, _: AccessContext) -> Result<(), MemoryError> {
                Ok(())
            }
        }

        let _guard = jit_test_lock();
        let block = od_jit::memory_load_v2::compile_ir_memory_dword_load_block_v2(
            CodeView::new(ENTRY, &source).unwrap(),
            ENTRY,
        )
        .unwrap();
        assert_eq!(
            block.site().operand().base,
            od_isa::long_decode::AddressBase::Register(base_register)
        );
        let published = PublishedCode::publish_ir_memory_dword_load_v2(&block).unwrap();
        let stop = AtomicU8::new(0);

        if displacement_bytes.as_ref().is_some_and(|bytes| bytes.len() == 4) {
            let encoded = displacement_bytes.as_ref().unwrap();
            for missing_byte in 0..4 {
                let mut ram = AliasRam {
                    bytes: BTreeMap::new(),
                    reads: Vec::new(),
                    read_error: None,
                    instruction_base,
                    instruction_displacement: Some(encoded[..missing_byte].to_vec()),
                    stop_on_read: None,
                };
                let mut state = od_isa::LongModeState {
                    rip: ENTRY,
                    ..Default::default()
                };
                state.gpr[base_gpr_index] = original_base;
                let before = state.clone();
                assert_eq!(
                    od_isa::execute::step(
                        &mut state,
                        &mut ram,
                        AccessContext::default(),
                    ),
                    Err(MemoryError::Unmapped {
                        address: ENTRY + 2 + missing_byte as u64,
                        access: AccessKind::Fetch,
                    }),
                    "missing disp32 byte {missing_byte} must propagate as a fetch error"
                );
                assert_eq!(state, before);
                assert!(ram.reads.is_empty());
            }
        }

        for value in [0_u32, 0x8000_0000, 0xffff_ffff] {
            let mut ram = AliasRam {
                bytes: BTreeMap::new(),
                reads: Vec::new(),
                read_error: None,
                instruction_base,
                instruction_displacement: displacement_bytes.clone(),
                stop_on_read: None,
            };
            let low32_decoy = u64::from(
                (original_base as u32).wrapping_add(displacement as u32),
            );
            for (offset, byte) in 0x1357_9bdf_u32.to_le_bytes().into_iter().enumerate() {
                ram.bytes.insert(low32_decoy + offset as u64, byte);
            }
            for (offset, byte) in value.to_le_bytes().into_iter().enumerate() {
                ram.bytes.insert(ADDRESS + offset as u64, byte);
            }
            let mut state = od_isa::LongModeState {
                rip: ENTRY,
                rflags: 0x8d7,
                ..Default::default()
            };
            state.gpr[base_gpr_index] = original_base;
            let mut expected_state = state.clone();
            let mut expected_ram = ram.clone();
            let result = published
                .execute_ir_memory_dword_load_v2(
                    &mut state,
                    &mut ram,
                    AccessContext::default(),
                    1,
                    None,
                    &stop,
                )
                .unwrap();
            assert_eq!(
                od_isa::execute::step(
                    &mut expected_state,
                    &mut expected_ram,
                    AccessContext::default(),
                )
                .unwrap(),
                od_isa::execute::StepOutcome::Advanced
            );
            assert_eq!(result.exit, MemoryOperationExecutionExitV2::Complete);
            assert_eq!(state, expected_state);
            assert_eq!(state.gpr[0], u64::from(value));
            if base_gpr_index != 0 {
                assert_eq!(state.gpr[base_gpr_index], original_base);
            }
            assert_eq!(state.rip, next_rip);
            assert_eq!(result.retired_instructions, 1);
            assert_eq!(ram.reads, [(ADDRESS, 4)]);
            assert_eq!(ram, expected_ram);
        }

        for (address, value) in [
            (0, 0x1020_3040_u32),
            (0xffff_8000_0000_1000, 0x2468_ace0_u32),
            (u64::MAX - 3, 0xdead_beef_u32),
        ] {
            let mut ram = AliasRam {
                bytes: BTreeMap::new(),
                reads: Vec::new(),
                read_error: None,
                instruction_base,
                instruction_displacement: displacement_bytes.clone(),
                stop_on_read: None,
            };
            for (offset, byte) in value.to_le_bytes().into_iter().enumerate() {
                ram.bytes.insert(address + offset as u64, byte);
            }
            let mut state = od_isa::LongModeState {
                rip: ENTRY,
                ..Default::default()
            };
            let original_base = base_for_address(address);
            state.gpr[base_gpr_index] = original_base;
            let result = published
                .execute_ir_memory_dword_load_v2(
                    &mut state,
                    &mut ram,
                    AccessContext::default(),
                    1,
                    None,
                    &stop,
                )
                .unwrap();
            assert_eq!(result.exit, MemoryOperationExecutionExitV2::Complete);
            assert_eq!(state.gpr[0], u64::from(value));
            if base_gpr_index != 0 {
                assert_eq!(state.gpr[base_gpr_index], original_base);
            }
            assert_eq!(state.rip, next_rip);
            assert_eq!(ram.reads, [(address, 4)]);
        }

        if displacement == 1 {
            let mut ram = AliasRam {
                bytes: BTreeMap::new(),
                reads: Vec::new(),
                read_error: None,
                instruction_base,
                instruction_displacement: displacement_bytes.clone(),
                stop_on_read: None,
            };
            for (offset, byte) in 0x6a5b_4c3d_u32.to_le_bytes().into_iter().enumerate() {
                ram.bytes.insert(offset as u64, byte);
            }
            let mut state = od_isa::LongModeState {
                rip: ENTRY,
                ..Default::default()
            };
            state.gpr[base_gpr_index] = u64::MAX;
            let mut expected_state = state.clone();
            let mut expected_ram = ram.clone();
            assert_eq!(
                od_isa::execute::step(
                    &mut expected_state,
                    &mut expected_ram,
                    AccessContext::default(),
                )
                .unwrap(),
                od_isa::execute::StepOutcome::Advanced
            );
            let result = published
                .execute_ir_memory_dword_load_v2(
                    &mut state,
                    &mut ram,
                    AccessContext::default(),
                    1,
                    None,
                    &stop,
                )
                .unwrap();
            assert_eq!(result.exit, MemoryOperationExecutionExitV2::Complete);
            assert_eq!(state, expected_state);
            assert_eq!(state.gpr[base_gpr_index], u64::MAX);
            assert_eq!(state.gpr[0], 0x6a5b_4c3d);
            assert_eq!(state.rip, next_rip);
            assert_eq!(ram.reads, [(0, 4)]);
        }

        if displacement == -4 {
            let raw_noncanonical_rcx = 0x0000_8000_0000_0000_u64;
            let canonical_ea = raw_noncanonical_rcx.wrapping_add_signed(-4);
            assert_eq!(canonical_ea, 0x0000_7fff_ffff_fffc);
            let mut ram = AliasRam {
                bytes: BTreeMap::new(),
                reads: Vec::new(),
                read_error: None,
                instruction_base,
                instruction_displacement: displacement_bytes.clone(),
                stop_on_read: None,
            };
            for (offset, byte) in 0x1029_3847_u32.to_le_bytes().into_iter().enumerate() {
                ram.bytes.insert(canonical_ea + offset as u64, byte);
            }
            let mut state = od_isa::LongModeState {
                rip: ENTRY,
                ..Default::default()
            };
            state.gpr[base_gpr_index] = raw_noncanonical_rcx;
            let mut expected_state = state.clone();
            let mut expected_ram = ram.clone();
            assert_eq!(
                od_isa::execute::step(
                    &mut expected_state,
                    &mut expected_ram,
                    AccessContext::default(),
                )
                .unwrap(),
                od_isa::execute::StepOutcome::Advanced
            );
            let result = published
                .execute_ir_memory_dword_load_v2(
                    &mut state,
                    &mut ram,
                    AccessContext::default(),
                    1,
                    None,
                    &stop,
                )
                .unwrap();
            assert_eq!(result.exit, MemoryOperationExecutionExitV2::Complete);
            assert_eq!(state, expected_state);
            assert_eq!(state.gpr[base_gpr_index], raw_noncanonical_rcx);
            assert_eq!(state.gpr[0], 0x1029_3847);
            assert_eq!(state.rip, next_rip);
            assert_eq!(ram.reads, [(canonical_ea, 4)]);
        }

        for (budget, stop_rip, stop_requested, expected_exit) in [
            (0, None, 0, MemoryOperationExecutionExitV2::BudgetExhausted),
            (
                1,
                Some(ENTRY),
                0,
                MemoryOperationExecutionExitV2::StopAddress,
            ),
            (1, None, 1, MemoryOperationExecutionExitV2::StopRequested),
        ] {
            let mut state = od_isa::LongModeState {
                rip: ENTRY,
                ..Default::default()
            };
            state.gpr[base_gpr_index] = original_base;
            let before = state.clone();
            let mut ram = AliasRam {
                bytes: BTreeMap::new(),
                reads: Vec::new(),
                read_error: None,
                instruction_base,
                instruction_displacement: displacement_bytes.clone(),
                stop_on_read: None,
            };
            for (offset, byte) in 0xcafe_f00d_u32.to_le_bytes().into_iter().enumerate() {
                ram.bytes.insert(ADDRESS + offset as u64, byte);
            }
            let stop_flag = AtomicU8::new(stop_requested);
            let result = published
                .execute_ir_memory_dword_load_v2(
                    &mut state,
                    &mut ram,
                    AccessContext::default(),
                    budget,
                    stop_rip,
                    &stop_flag,
                )
                .unwrap();
            assert_eq!(result.exit, expected_exit);
            assert_eq!(result.retired_instructions, 0);
            assert_eq!(result.remaining_budget, budget);
            assert!(ram.reads.is_empty());
            assert_eq!(state, before);
            stop_flag.store(0, Ordering::Release);
            let retried = published
                .execute_ir_memory_dword_load_v2(
                    &mut state,
                    &mut ram,
                    AccessContext::default(),
                    1,
                    None,
                    &stop_flag,
                )
                .unwrap();
            assert_eq!(retried.exit, MemoryOperationExecutionExitV2::Complete);
            assert_eq!(retried.retired_instructions, 1);
            assert_eq!(state.gpr[0], 0xcafe_f00d);
            if base_gpr_index != 0 {
                assert_eq!(state.gpr[base_gpr_index], original_base);
            }
            assert_eq!(state.rip, next_rip);
            assert_eq!(ram.reads, [(ADDRESS, 4)]);
        }

        let mut wrong_rip_state = od_isa::LongModeState {
            rip: ENTRY + 1,
            ..Default::default()
        };
        wrong_rip_state.gpr[base_gpr_index] = original_base;
        let wrong_rip_before = wrong_rip_state.clone();
        let mut wrong_rip_ram = AliasRam {
            bytes: BTreeMap::new(),
            reads: Vec::new(),
            read_error: None,
            instruction_base,
            instruction_displacement: displacement_bytes.clone(),
            stop_on_read: None,
        };
        for (offset, byte) in 0x7654_3210_u32.to_le_bytes().into_iter().enumerate() {
            wrong_rip_ram.bytes.insert(ADDRESS + offset as u64, byte);
        }
        assert!(matches!(
            published.execute_ir_memory_dword_load_v2(
                &mut wrong_rip_state,
                &mut wrong_rip_ram,
                AccessContext::default(),
                1,
                None,
                &stop,
            ),
            Err(MemoryOperationExecutionErrorV2::EntryRipMismatch {
                expected: ENTRY,
                actual,
            })
                if actual == ENTRY + 1
        ));
        assert_eq!(wrong_rip_state, wrong_rip_before);
        assert!(wrong_rip_ram.reads.is_empty());
        wrong_rip_state.rip = ENTRY;
        let wrong_rip_retry = published
            .execute_ir_memory_dword_load_v2(
                &mut wrong_rip_state,
                &mut wrong_rip_ram,
                AccessContext::default(),
                1,
                None,
                &stop,
            )
            .unwrap();
        assert_eq!(wrong_rip_retry.exit, MemoryOperationExecutionExitV2::Complete);
        assert_eq!(wrong_rip_state.gpr[0], 0x7654_3210);
        if base_gpr_index != 0 {
            assert_eq!(wrong_rip_state.gpr[base_gpr_index], original_base);
        }
        assert_eq!(wrong_rip_state.rip, next_rip);
        assert_eq!(wrong_rip_ram.reads, [(ADDRESS, 4)]);

        let fault = MemoryError::Architectural(od_isa::memory::ArchitecturalFault {
            vector: 14,
            error_code: Some(0x5),
            linear_address: Some(ADDRESS),
        });
        let mut ram = AliasRam {
            bytes: BTreeMap::new(),
            reads: Vec::new(),
            read_error: Some(fault.clone()),
            instruction_base,
            instruction_displacement: displacement_bytes.clone(),
            stop_on_read: None,
        };
        let mut state = od_isa::LongModeState {
            rip: ENTRY,
            ..Default::default()
        };
        state.gpr[base_gpr_index] = original_base;
        let before = state.clone();
        let failed = published
            .execute_ir_memory_dword_load_v2(
                &mut state,
                &mut ram,
                AccessContext::default(),
                1,
                None,
                &stop,
            )
            .unwrap();
        assert_eq!(
            failed.exit,
            MemoryOperationExecutionExitV2::GuestFault(od_isa::memory::ArchitecturalFault {
                vector: 14,
                error_code: Some(0x5),
                linear_address: Some(ADDRESS),
            })
        );
        assert_eq!(failed.retired_instructions, 0);
        assert_eq!(state, before);
        assert_eq!(ram.reads, [(ADDRESS, 4)]);
        assert!(ram.bytes.is_empty());
        ram.read_error = None;
        for (offset, byte) in 0xfeed_beef_u32.to_le_bytes().into_iter().enumerate() {
            ram.bytes.insert(ADDRESS + offset as u64, byte);
        }
        let guest_fault_retry = published
            .execute_ir_memory_dword_load_v2(
                &mut state,
                &mut ram,
                AccessContext::default(),
                1,
                None,
                &stop,
            )
            .unwrap();
        assert_eq!(guest_fault_retry.exit, MemoryOperationExecutionExitV2::Complete);
        assert_eq!(state.gpr[0], 0xfeed_beef);
        if base_gpr_index != 0 {
            assert_eq!(state.gpr[base_gpr_index], original_base);
        }
        assert_eq!(state.rip, next_rip);
        assert_eq!(ram.reads, [(ADDRESS, 4), (ADDRESS, 4)]);

        let backend_error = MemoryError::Unmapped {
            address: ADDRESS,
            access: AccessKind::Read,
        };
        let mut ram = AliasRam {
            bytes: BTreeMap::new(),
            reads: Vec::new(),
            read_error: Some(backend_error),
            instruction_base,
            instruction_displacement: displacement_bytes.clone(),
            stop_on_read: None,
        };
        state = before.clone();
        let backend = published.execute_ir_memory_dword_load_v2(
            &mut state,
            &mut ram,
            AccessContext::default(),
            1,
            None,
            &stop,
        );
        assert!(matches!(
            backend,
            Err(MemoryOperationExecutionErrorV2::MemoryError(
                MemoryOperationMemoryErrorV2 {
                    kind: od_jit::memory_bridge::MEMORY_ERROR_UNMAPPED,
                    address: ADDRESS,
                    length: 0,
                }
            ))
        ));
        assert_eq!(state, before);
        assert_eq!(ram.reads, [(ADDRESS, 4)]);
        assert!(ram.bytes.is_empty());
        ram.read_error = None;
        for (offset, byte) in 0x0bad_c0de_u32.to_le_bytes().into_iter().enumerate() {
            ram.bytes.insert(ADDRESS + offset as u64, byte);
        }
        let backend_retry = published
            .execute_ir_memory_dword_load_v2(
                &mut state,
                &mut ram,
                AccessContext::default(),
                1,
                None,
                &stop,
            )
            .unwrap();
        assert_eq!(backend_retry.exit, MemoryOperationExecutionExitV2::Complete);
        assert_eq!(state.gpr[0], 0x0bad_c0de);
        if base_gpr_index != 0 {
            assert_eq!(state.gpr[base_gpr_index], original_base);
        }
        assert_eq!(state.rip, next_rip);
        assert_eq!(ram.reads, [(ADDRESS, 4), (ADDRESS, 4)]);

        for address in [0x0000_8000_0000_0000, 0x0000_7fff_ffff_fffd] {
            let mut state = od_isa::LongModeState {
                rip: ENTRY,
                ..Default::default()
            };
            state.gpr[base_gpr_index] = base_for_address(address);
            let before = state.clone();
            let mut ram = AliasRam {
                bytes: BTreeMap::new(),
                reads: Vec::new(),
                read_error: None,
                instruction_base,
                instruction_displacement: displacement_bytes.clone(),
                stop_on_read: None,
            };
            let result = published
                .execute_ir_memory_dword_load_v2(
                    &mut state,
                    &mut ram,
                    AccessContext::default(),
                    1,
                    None,
                    &stop,
                )
                .unwrap();
            assert!(matches!(
                result.exit,
                MemoryOperationExecutionExitV2::GuestFault(_)
            ));
            assert_eq!(result.retired_instructions, 0);
            assert_eq!(state, before);
            assert!(ram.reads.is_empty());
        }

        let mut state = od_isa::LongModeState {
            rip: ENTRY,
            ..Default::default()
        };
        state.gpr[base_gpr_index] = base_for_address(u64::MAX - 1);
        let before = state.clone();
        let mut ram = AliasRam {
            bytes: BTreeMap::new(),
            reads: Vec::new(),
            read_error: None,
            instruction_base,
            instruction_displacement: displacement_bytes.clone(),
            stop_on_read: None,
        };
        let overflow = published.execute_ir_memory_dword_load_v2(
            &mut state,
            &mut ram,
            AccessContext::default(),
            1,
            None,
            &stop,
        );
        assert!(matches!(
            overflow,
            Err(MemoryOperationExecutionErrorV2::MemoryError(
                MemoryOperationMemoryErrorV2 {
                    kind: od_jit::memory_bridge::MEMORY_ERROR_ADDRESS_OVERFLOW,
                    address,
                    length: 4,
                }
            )) if address == u64::MAX - 1
        ));
        assert_eq!(state, before);
        assert!(ram.reads.is_empty());

        let callback_stop = Arc::new(AtomicU8::new(0));
        let mut stopped_state = od_isa::LongModeState {
            rip: ENTRY,
            rflags: 0x8d7,
            ..Default::default()
        };
        stopped_state.gpr[base_gpr_index] = original_base;
        let mut stopped_ram = AliasRam {
            bytes: BTreeMap::new(),
            reads: Vec::new(),
            read_error: None,
            instruction_base,
            instruction_displacement: displacement_bytes.clone(),
            stop_on_read: Some(callback_stop.clone()),
        };
        for (offset, byte) in 0xa5a5_5a5a_u32.to_le_bytes().into_iter().enumerate() {
            stopped_ram.bytes.insert(ADDRESS + offset as u64, byte);
        }
        let stopped = published
            .execute_ir_memory_dword_load_v2(
                &mut stopped_state,
                &mut stopped_ram,
                AccessContext::default(),
                1,
                None,
                &callback_stop,
            )
            .unwrap();
        assert_eq!(stopped.exit, MemoryOperationExecutionExitV2::StopRequested);
        assert_eq!(stopped.retired_instructions, 1);
        assert_eq!(stopped_state.gpr[0], 0xa5a5_5a5a);
        if base_gpr_index != 0 {
            assert_eq!(stopped_state.gpr[base_gpr_index], original_base);
        }
        assert_eq!(stopped_state.rflags, 0x8d7);
        assert_eq!(stopped_state.rip, next_rip);
        assert_eq!(stopped_ram.reads, [(ADDRESS, 4)]);
        assert!(matches!(
            published.execute_ir_memory_dword_load_v2(
                &mut stopped_state,
                &mut stopped_ram,
                AccessContext::default(),
                1,
                None,
                &callback_stop,
            ),
            Err(MemoryOperationExecutionErrorV2::EntryRipMismatch {
                expected: ENTRY,
                actual,
            })
                if actual == next_rip
        ));
        assert_eq!(stopped_state.rip, next_rip);
        assert_eq!(stopped_ram.reads, [(ADDRESS, 4)]);
    }

