            state.gpr[2] = 0x8877_6655_4433_2211;
            state.gpr[3] = base;
            state.gpr[4] = 0x1234_5678_9abc_def0;
            state.gpr[5] = 0x0fed_cba9_8765_4321;
            state.gpr[6] = 0x55aa_55aa_33cc_33cc;
