    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    fn s3_20cu_disp32_dword_store_preserves_checked_semantics() {
        use od_isa::memory::{AccessContext, AccessKind, GuestMemory, MemoryError};
        use std::collections::BTreeMap;
        use std::sync::Arc;

        const ENTRY: u64 = 0x9f80;

        #[derive(Clone, Debug)]
        struct SparseRam {
            code: Vec<u8>,
            bytes: BTreeMap<u64, u8>,
            writes: Vec<(u64, Vec<u8>)>,
            write_error: Option<MemoryError>,
            stop_on_write: Option<Arc<AtomicU8>>,
        }

        impl GuestMemory for SparseRam {
            fn fetch(&mut self, address: u64, _: AccessContext) -> Result<u8, MemoryError> {
                if let Some(offset) = address
                    .checked_sub(ENTRY)
                    .and_then(|offset| usize::try_from(offset).ok())
                    .filter(|offset| *offset < self.code.len())
                {
                    return Ok(self.code[offset]);
                }
                self.bytes
                    .get(&address)
                    .copied()
                    .ok_or(MemoryError::Unmapped {
                        address,
                        access: AccessKind::Fetch,
                    })
            }

            fn read(
                &mut self,
                address: u64,
                _: AccessContext,
                output: &mut [u8],
            ) -> Result<(), MemoryError> {
                for (offset, byte) in output.iter_mut().enumerate() {
                    *byte = *self.bytes.get(&(address + offset as u64)).ok_or(
                        MemoryError::Unmapped {
                            address,
                            access: AccessKind::Read,
                        },
                    )?;
                }
                Ok(())
            }

            fn write(
                &mut self,
                address: u64,
                _: AccessContext,
                input: &[u8],
            ) -> Result<(), MemoryError> {
                self.writes.push((address, input.to_vec()));
                if let Some(error) = self.write_error.clone() {
                    return Err(error);
                }
                for (offset, byte) in input.iter().copied().enumerate() {
                    self.bytes.insert(address + offset as u64, byte);
                }
                if let Some(stop) = &self.stop_on_write {
                    stop.store(1, Ordering::Release);
                }
                Ok(())
            }

            fn atomic_exchange_integer(
                &mut self,
                address: u64,
                _: AccessContext,
                _: od_isa::OperandSize,
                _: u64,
            ) -> Result<u64, MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn atomic_fetch_add_integer(
                &mut self,
                address: u64,
                _: AccessContext,
                _: od_isa::OperandSize,
                _: u64,
            ) -> Result<u64, MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn atomic_compare_exchange_integer(
                &mut self,
                address: u64,
                _: AccessContext,
                _: od_isa::OperandSize,
                _: u64,
                _: u64,
            ) -> Result<u64, MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn mfence(&mut self, _: AccessContext) -> Result<(), MemoryError> {
                Ok(())
            }
        }

        fn ram_for(source: [u8; 6], address: u64) -> SparseRam {
            let mut bytes = BTreeMap::new();
            for offset in 0..8 {
                bytes.insert(address - 2 + offset, 0x60 + offset as u8);
            }
            SparseRam {
                code: source.to_vec(),
                bytes,
                writes: Vec::new(),
                write_error: None,
                stop_on_write: None,
            }
        }

        let _guard = jit_test_lock();
        for (case_index, signed_displacement) in [
            i32::MIN,
            -129,
            -128,
            -2,
            -1,
            0,
            1,
            127,
            128,
            0x0102_0304,
            0x7f00_ff80,
            i32::MAX,
        ]
        .into_iter()
        .enumerate()
        {
            let displacement = signed_displacement.to_le_bytes();
            let source = [
                0x89,
                0x83,
                displacement[0],
                displacement[1],
                displacement[2],
                displacement[3],
            ];
            let signed_displacement = i64::from(signed_displacement);
            let address = if signed_displacement == -2 {
                0xffff_fffe
            } else {
                0x1_0000_1001 + (case_index as u64) * 8
            };
            let base = address.wrapping_sub(signed_displacement as u64);
            let compiled = od_jit::memory_load_v2::compile_ir_memory_dword_store_block_v2(
                CodeView::new(ENTRY, &source).unwrap(),
                ENTRY,
            )
            .unwrap();
            assert_eq!(compiled.site().operand().displacement, signed_displacement);
            assert_eq!(compiled.site().next_rip(), ENTRY + 6);
            let expected_map = compiled.pc_map().clone();
            let published = PublishedCode::publish_ir_memory_dword_store_v2(&compiled).unwrap();
            drop(compiled);
            assert_eq!(published.pc_map(), Some(&expected_map));

            let mut native_ram = ram_for(source, address);
            let mut interpreter_ram = native_ram.clone();
            let mut base_state = od_isa::LongModeState {
                rip: ENTRY,
                rflags: 0x8d7,
                ..Default::default()
            };
            base_state.gpr[0] = 0xfedc_ba98_89ab_cdef;
            base_state.gpr[1] = 0x1122_3344_5566_7788;
            base_state.gpr[2] = 0x8877_6655_4433_2211;
            base_state.gpr[3] = base;
            let mut native_state = base_state.clone();
            let mut interpreter_state = base_state;
            let stop = AtomicU8::new(0);
            // SAFETY: the fixture uses private synchronous ordinary RAM; its
            // four-byte write callback is all-or-nothing and does not alias code.
            let native = unsafe {
                published.execute_ir_memory_dword_store_v2(
                    &mut native_state,
                    &mut native_ram,
                    AccessContext::default(),
                    1,
                    None,
                    &stop,
                )
            }
            .unwrap();
            let interpreted = od_isa::execute::step(
                &mut interpreter_state,
                &mut interpreter_ram,
                AccessContext::default(),
            )
            .unwrap();
            assert_eq!(native.exit, MemoryOperationExecutionExitV2::Complete);
            assert_eq!(interpreted, od_isa::execute::StepOutcome::Advanced);
            assert_eq!(native_state, interpreter_state);
            assert_eq!(native_state.gpr[0], 0xfedc_ba98_89ab_cdef);
            assert_eq!(native_state.gpr[1], 0x1122_3344_5566_7788);
            assert_eq!(native_state.gpr[2], 0x8877_6655_4433_2211);
            assert_eq!(native_state.gpr[3], base);
            assert_eq!(native_state.rflags, 0x8d7);
            assert_eq!(native_state.rip, ENTRY + 6);
            assert_eq!(native.retired_instructions, 1);
            assert_eq!(
                native_ram.writes,
                [(address, 0x89ab_cdef_u32.to_le_bytes().to_vec())]
            );
            assert_eq!(native_ram.bytes, interpreter_ram.bytes);
            assert_eq!(native_ram.writes, interpreter_ram.writes);
            assert_eq!(native_ram.bytes[&(address - 2)], 0x60);
            assert_eq!(native_ram.bytes[&(address - 1)], 0x61);
            assert_eq!(native_ram.bytes[&(address + 4)], 0x66);
            assert_eq!(native_ram.bytes[&(address + 5)], 0x67);
            drop(published);
        }

        let source = [0x89, 0x83, 0, 0, 0, 0];
        let address = 0x1_0000_3000;
        let compiled = od_jit::memory_load_v2::compile_ir_memory_dword_store_block_v2(
            CodeView::new(ENTRY, &source).unwrap(),
            ENTRY,
        )
        .unwrap();
        let published = PublishedCode::publish_ir_memory_dword_store_v2(&compiled).unwrap();
        let mut before = od_isa::LongModeState {
            rip: ENTRY,
            rflags: 0x8d7,
            ..Default::default()
        };
        before.gpr[0] = 0xfedc_ba98_89ab_cdef;
        before.gpr[3] = address;

        for (budget, stop_rip, stop_requested, expected_exit) in [
            (0, None, 0, MemoryOperationExecutionExitV2::BudgetExhausted),
            (
                1,
                Some(ENTRY),
                0,
                MemoryOperationExecutionExitV2::StopAddress,
            ),
            (1, None, 1, MemoryOperationExecutionExitV2::StopRequested),
        ] {
            let mut ram = ram_for(source, address);
            let mut state = before.clone();
            let stop = AtomicU8::new(stop_requested);
            // SAFETY: ram_for creates private ordinary RAM with atomic writes.
            let result = unsafe {
                published.execute_ir_memory_dword_store_v2(
                    &mut state,
                    &mut ram,
                    AccessContext::default(),
                    budget,
                    stop_rip,
                    &stop,
                )
            }
            .unwrap();
            assert_eq!(result.exit, expected_exit);
            assert_eq!(result.retired_instructions, 0);
            assert_eq!(result.remaining_budget, budget);
            assert!(ram.writes.is_empty());
            assert_eq!(state, before);
        }

        let callback_stop = Arc::new(AtomicU8::new(0));
        let mut callback_ram = ram_for(source, address);
        callback_ram.stop_on_write = Some(callback_stop.clone());
        let mut callback_state = before.clone();
        // SAFETY: callback_ram is private ordinary RAM with an all-or-nothing write.
        let callback = unsafe {
            published.execute_ir_memory_dword_store_v2(
                &mut callback_state,
                &mut callback_ram,
                AccessContext::default(),
                1,
                None,
                &callback_stop,
            )
        }
        .unwrap();
        assert_eq!(callback.exit, MemoryOperationExecutionExitV2::StopRequested);
        assert_eq!(callback.retired_instructions, 1);
        assert_eq!(callback_state.rip, ENTRY + 6);
        assert_eq!(callback_state.gpr[0], before.gpr[0]);
        assert_eq!(
            callback_ram.writes,
            [(address, 0x89ab_cdef_u32.to_le_bytes().to_vec())]
        );

        for error in [
            MemoryError::Architectural(od_isa::memory::ArchitecturalFault {
                vector: 14,
                error_code: Some(0),
                linear_address: Some(address),
            }),
            MemoryError::Unmapped {
                address,
                access: AccessKind::Write,
            },
        ] {
            let mut ram = ram_for(source, address);
            ram.write_error = Some(error.clone());
            let before_bytes = ram.bytes.clone();
            let mut state = before.clone();
            let result = unsafe {
                published.execute_ir_memory_dword_store_v2(
                    &mut state,
                    &mut ram,
                    AccessContext::default(),
                    1,
                    None,
                    &AtomicU8::new(0),
                )
            };
            assert_eq!(state, before);
            assert_eq!(ram.bytes, before_bytes);
            assert_eq!(
                ram.writes,
                [(address, 0x89ab_cdef_u32.to_le_bytes().to_vec())]
            );
            match error {
                MemoryError::Architectural(fault) => {
                    let result = result.unwrap();
                    assert_eq!(
                        result.exit,
                        MemoryOperationExecutionExitV2::GuestFault(fault)
                    );
                    assert_eq!(result.retired_instructions, 0);
                }
                MemoryError::Unmapped { .. } => assert_eq!(
                    result,
                    Err(MemoryOperationExecutionErrorV2::MemoryError(
                        MemoryOperationMemoryErrorV2 {
                            kind: od_jit::memory_bridge::MEMORY_ERROR_UNMAPPED,
                            address,
                            length: 0,
                        }
                    ))
                ),
                _ => unreachable!(),
            }
        }

        let noncanonical_source = [0x89, 0x83, 0, 0, 0, 0];
        let mut noncanonical_ram = ram_for(noncanonical_source, 0x0000_8000_0000_0000);
        let noncanonical_before_bytes = noncanonical_ram.bytes.clone();
        let mut noncanonical_state = before.clone();
        noncanonical_state.gpr[3] = 0x0000_8000_0000_0000;
        let noncanonical_before = noncanonical_state.clone();
        let result = unsafe {
            published.execute_ir_memory_dword_store_v2(
                &mut noncanonical_state,
                &mut noncanonical_ram,
                AccessContext::default(),
                1,
                None,
                &AtomicU8::new(0),
            )
        }
        .unwrap();
        assert_eq!(
            result.exit,
            MemoryOperationExecutionExitV2::GuestFault(od_isa::memory::ArchitecturalFault {
                vector: 13,
                error_code: Some(0),
                linear_address: None,
            })
        );
        assert_eq!(noncanonical_state, noncanonical_before);
        assert!(noncanonical_ram.writes.is_empty());
        assert_eq!(noncanonical_ram.bytes, noncanonical_before_bytes);
    }

    #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
    #[test]
    fn s3_20de_rbx_rcx_sib_dword_store_uses_full_width_base_and_index() {
        use od_isa::memory::{AccessContext, AccessKind, GuestMemory, MemoryError};
        use std::collections::BTreeMap;
        use std::sync::Arc;

        const ENTRY: u64 = 0x9f70;
        const SOURCE: [u8; 3] = [0x89, 0x04, 0x0b];
        const VALUE: u32 = 0x89ab_cdef;

        #[derive(Clone, Debug)]
        struct Ram {
            code: Vec<u8>,
            bytes: BTreeMap<u64, u8>,
            writes: Vec<(u64, Vec<u8>)>,
            write_error: Option<MemoryError>,
            stop_on_write: Option<Arc<AtomicU8>>,
        }

        impl GuestMemory for Ram {
            fn fetch(&mut self, address: u64, _: AccessContext) -> Result<u8, MemoryError> {
                if let Some(offset) = address
                    .checked_sub(ENTRY)
                    .and_then(|offset| usize::try_from(offset).ok())
                    .filter(|offset| *offset < self.code.len())
                {
                    return Ok(self.code[offset]);
                }
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Fetch,
                })
            }

            fn read(
                &mut self,
                address: u64,
                _: AccessContext,
                output: &mut [u8],
            ) -> Result<(), MemoryError> {
                for (offset, byte) in output.iter_mut().enumerate() {
                    *byte = *self.bytes.get(&(address + offset as u64)).ok_or(
                        MemoryError::Unmapped {
                            address,
                            access: AccessKind::Read,
                        },
                    )?;
                }
                Ok(())
            }

            fn write(
                &mut self,
                address: u64,
                _: AccessContext,
                input: &[u8],
            ) -> Result<(), MemoryError> {
                self.writes.push((address, input.to_vec()));
                if let Some(error) = self.write_error.clone() {
                    return Err(error);
                }
                for (offset, byte) in input.iter().copied().enumerate() {
                    self.bytes.insert(address + offset as u64, byte);
                }
                if let Some(stop) = &self.stop_on_write {
                    stop.store(1, Ordering::Release);
                }
                Ok(())
            }

            fn atomic_exchange_integer(
                &mut self,
                address: u64,
                _: AccessContext,
                _: od_isa::OperandSize,
                _: u64,
            ) -> Result<u64, MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn atomic_fetch_add_integer(
                &mut self,
                address: u64,
                _: AccessContext,
                _: od_isa::OperandSize,
                _: u64,
            ) -> Result<u64, MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn atomic_compare_exchange_integer(
                &mut self,
                address: u64,
                _: AccessContext,
                _: od_isa::OperandSize,
                _: u64,
                _: u64,
            ) -> Result<u64, MemoryError> {
                Err(MemoryError::Unmapped {
                    address,
                    access: AccessKind::Write,
                })
            }

            fn mfence(&mut self, _: AccessContext) -> Result<(), MemoryError> {
                Ok(())
            }
        }

        fn state_for(rbx: u64, rcx: u64) -> od_isa::LongModeState {
            let mut state = od_isa::LongModeState {
                rip: ENTRY,
                rflags: 0x8d7,
                ..Default::default()
            };
            state.gpr[0] = 0xfedc_ba98_89ab_cdef;
            state.gpr[1] = rcx;
            state.gpr[2] = 0x8877_6655_4433_2211;
            state.gpr[3] = rbx;
            state.gpr[4] = 0x1234_5678_9abc_def0;
            state.gpr[5] = 0x0fed_cba9_8765_4321;
            state.gpr[6] = 0x55aa_55aa_33cc_33cc;
            state.gpr[7] = 0xaa55_aa55_cc33_cc33;
            state
        }

        fn ram_for(target: u64) -> Ram {
            let bytes = (-1_i64..=4)
                .map(|offset| {
                    (
                        target.wrapping_add_signed(offset),
                        0x60 + (offset + 1) as u8,
                    )
                })
                .collect();
            Ram {
                code: SOURCE.to_vec(),
                bytes,
                writes: Vec::new(),
                write_error: None,
                stop_on_write: None,
            }
        }

        let _guard = jit_test_lock();
        let compiled = od_jit::memory_load_v2::compile_ir_memory_dword_store_block_v2(
            CodeView::new(ENTRY, &SOURCE).unwrap(),
            ENTRY,
        )
        .unwrap();
        assert_eq!(compiled.site().next_rip(), ENTRY + 3);
        assert_eq!(
            compiled.site().operand().base,
            od_isa::long_decode::AddressBase::Register(od_isa::Register::Rbx)
        );
        assert_eq!(compiled.site().operand().index, Some(od_isa::Register::Rcx));
        assert_eq!(compiled.site().operand().scale, 1);
        assert_eq!(compiled.site().operand().size, od_isa::OperandSize::Dword);
        let site = *compiled.site();
        let expected_map = compiled.pc_map().clone();
        let published = PublishedCode::publish_ir_memory_dword_store_v2(&compiled).unwrap();
        drop(compiled);
        assert_eq!(published.pc_map(), Some(&expected_map));

        let cases = [
            (
                0x0000_7000_0000_1000,
                0x0000_0001_0000_0015,
                0x0000_7001_0000_1015,
            ),
            (
                0x0000_0001_0000_2001,
                0x0000_0002_0000_0002,
                0x0000_0003_0000_2003,
            ),
        ];
        for (rbx, rcx, target) in cases {
            let before = state_for(rbx, rcx);
            let mut native_state = before.clone();
            let mut native_ram = ram_for(target);
            let mut interpreter_state = before.clone();
            let mut interpreter_ram = native_ram.clone();
            assert_eq!(
                site.operand().access_address_48(&before, ENTRY + 3),
                Ok(target)
            );
            let native = unsafe {
                published.execute_ir_memory_dword_store_v2(
                    &mut native_state,
                    &mut native_ram,
                    AccessContext::default(),
                    1,
                    None,
                    &AtomicU8::new(0),
                )
            }
            .unwrap();
            let interpreted = od_isa::execute::step(
                &mut interpreter_state,
                &mut interpreter_ram,
                AccessContext::default(),
            )
            .unwrap();
            assert_eq!(native.exit, MemoryOperationExecutionExitV2::Complete);
            assert_eq!(interpreted, od_isa::execute::StepOutcome::Advanced);
            assert_eq!(native.retired_instructions, 1);
            assert_eq!(native_state, interpreter_state);
            let mut expected_state = before.clone();
            expected_state.rip = ENTRY + 3;
            assert_eq!(native_state, expected_state);
            assert_eq!(native_ram.writes, [(target, VALUE.to_le_bytes().to_vec())]);
            assert_eq!(native_ram.bytes, interpreter_ram.bytes);
            assert_eq!(native_ram.writes, interpreter_ram.writes);
            assert_eq!(native_ram.bytes[&(target - 1)], 0x60);
            assert_eq!(native_ram.bytes[&(target + 4)], 0x65);
            assert_eq!(
                std::array::from_fn::<_, 4, _>(|offset| native_ram.bytes[&(target + offset as u64)]),
                VALUE.to_le_bytes()
            );

            if target == cases[0].2 {
                for (budget, stop_rip, requested, expected_exit) in [
                    (0, None, 0, MemoryOperationExecutionExitV2::BudgetExhausted),
                    (
                        1,
                        Some(ENTRY),
                        0,
                        MemoryOperationExecutionExitV2::StopAddress,
                    ),
                    (1, None, 1, MemoryOperationExecutionExitV2::StopRequested),
                ] {
                    let mut state = before.clone();
                    let mut ram = ram_for(target);
                    let before_bytes = ram.bytes.clone();
                    let result = unsafe {
                        published.execute_ir_memory_dword_store_v2(
                            &mut state,
                            &mut ram,
                            AccessContext::default(),
                            budget,
                            stop_rip,
                            &AtomicU8::new(requested),
                        )
                    }
                    .unwrap();
                    assert_eq!(result.exit, expected_exit);
                    assert_eq!(result.retired_instructions, 0);
                    assert_eq!(state, before);
                    assert!(ram.writes.is_empty());
                    assert_eq!(ram.bytes, before_bytes);
                }

                let callback_stop = Arc::new(AtomicU8::new(0));
                let mut callback_state = before.clone();
                let mut callback_ram = ram_for(target);
                callback_ram.stop_on_write = Some(callback_stop.clone());
                let callback = unsafe {
                    published.execute_ir_memory_dword_store_v2(
                        &mut callback_state,
                        &mut callback_ram,
                        AccessContext::default(),
                        1,
                        None,
                        &callback_stop,
                    )
                }
                .unwrap();
                assert_eq!(callback.exit, MemoryOperationExecutionExitV2::StopRequested);
                assert_eq!(callback.retired_instructions, 1);
                let mut committed = before.clone();
                committed.rip = ENTRY + 3;
                assert_eq!(callback_state, committed);
                assert_eq!(
                    callback_ram.writes,
                    [(target, VALUE.to_le_bytes().to_vec())]
                );

                for error in [
                    MemoryError::Architectural(od_isa::memory::ArchitecturalFault {
                        vector: 14,
                        error_code: Some(0),
                        linear_address: Some(target),
                    }),
                    MemoryError::Unmapped {
                        address: target,
                        access: AccessKind::Write,
                    },
                ] {
                    let mut state = before.clone();
                    let mut ram = ram_for(target);
                    ram.write_error = Some(error.clone());
                    let before_bytes = ram.bytes.clone();
                    let result = unsafe {
                        published.execute_ir_memory_dword_store_v2(
                            &mut state,
                            &mut ram,
                            AccessContext::default(),
                            1,
                            None,
                            &AtomicU8::new(0),
                        )
                    };
                    assert_eq!(state, before);
                    assert_eq!(ram.bytes, before_bytes);
                    assert_eq!(ram.writes, [(target, VALUE.to_le_bytes().to_vec())]);
                    match error {
                        MemoryError::Architectural(fault) => {
                            let result = result.unwrap();
                            assert_eq!(
                                result.exit,
                                MemoryOperationExecutionExitV2::GuestFault(fault)
                            );
                            assert_eq!(result.retired_instructions, 0);
                        }
                        MemoryError::Unmapped { .. } => assert_eq!(
                            result,
                            Err(MemoryOperationExecutionErrorV2::MemoryError(
                                MemoryOperationMemoryErrorV2 {
                                    kind: od_jit::memory_bridge::MEMORY_ERROR_UNMAPPED,
                                    address: target,
                                    length: 0,
                                }
                            ))
                        ),
                        _ => unreachable!(),
                    }
                }
            }
        }

        let mut noncanonical_state = state_for(0x0000_7fff_ffff_fffd, 1);
        let noncanonical_before = noncanonical_state.clone();
        let noncanonical_target = 0x0000_7fff_ffff_fffe;
        let mut noncanonical_ram = ram_for(noncanonical_target);
        let noncanonical_before_bytes = noncanonical_ram.bytes.clone();
        let result = unsafe {
            published.execute_ir_memory_dword_store_v2(
                &mut noncanonical_state,
                &mut noncanonical_ram,
                AccessContext::default(),
                1,
                None,
                &AtomicU8::new(0),
            )
        }
        .unwrap();
        assert_eq!(
            result.exit,
            MemoryOperationExecutionExitV2::GuestFault(od_isa::memory::ArchitecturalFault {
                vector: 13,
                error_code: Some(0),
                linear_address: None,
            })
        );
        assert_eq!(result.retired_instructions, 0);
        assert_eq!(noncanonical_state, noncanonical_before);
        assert!(noncanonical_ram.writes.is_empty());
        assert_eq!(noncanonical_ram.bytes, noncanonical_before_bytes);
    }

